import { useState } from 'react';
import {
  JxToggle,
  JxSlider,
  JxSwitch,
  JxDivider,
  JxSelect,
  JxBadge,
} from '@jinx-ui/react';

type ThemeValue = 'light' | 'dark' | 'auto';

export interface AppearanceSettings {
  theme: ThemeValue;
  scale: number;
  compact: boolean;
  font: string;
}

const themes: { value: ThemeValue; label: string }[] = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'auto', label: 'Системная' },
];

const defaults: AppearanceSettings = {
  theme: 'dark',
  scale: 100,
  compact: false,
  font: 'sans',
};

export default function AppearanceSettingsScreen({
  onChange,
}: {
  onChange?: (settings: AppearanceSettings) => void;
}) {
  const [settings, setSettings] = useState<AppearanceSettings>(defaults);

  const update = (patch: Partial<AppearanceSettings>) => {
    setSettings((prev) => {
      const next = { ...prev, ...patch };
      onChange?.(next);
      return next;
    });
  };

  const themeLabel = themes.find((item) => item.value === settings.theme)?.label ?? '';

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        padding: '24px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        color: 'var(--jx-text)',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <header style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
        <h2
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            fontSize: '20px',
          }}
        >
          Внешний вид
        </h2>
        <JxBadge tone="accent" dot>
          {themeLabel}
        </JxBadge>
      </header>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        <span style={{ color: 'var(--jx-text-2)', fontSize: '13px' }}>Тема</span>
        <JxToggle
          items={themes}
          value={settings.theme}
          onValueChange={(value) => update({ theme: value as ThemeValue })}
        />
      </div>

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={10}
        unit="%"
        showOutput
        value={settings.scale}
        onValueChange={(value) => update({ scale: value })}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={settings.compact}
        onChange={(event) => update({ compact: event.target.checked })}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт"
        options={[
          { value: 'sans', label: 'Inter Tight', meta: 'по умолчанию' },
          { value: 'display', label: 'Fraunces' },
          { value: 'mono', label: 'JetBrains Mono' },
        ]}
        value={settings.font}
        onValueChange={(value) => update({ font: value })}
      />
    </section>
  );
}

